'use strict';
const assert=require('node:assert/strict'),path=require('node:path'),{execFileSync}=require('node:child_process');
const {parseProcessRows}=require('./browserProcessOwnership');
function validateManagedIdentity({rows,browserPid,workerPid,uid,profile,root,executable,args,startIdentity,command}){
 assert.ok(Number.isSafeInteger(browserPid)&&browserPid>0&&browserPid!==workerPid);assert.ok(path.isAbsolute(root));assert.equal(profile,path.join(root,'csrf-managed-profile'));assert.ok(path.isAbsolute(executable));assert.ok(args.includes('--user-data-dir='+profile));assert.equal(args[0],executable);assert.equal(typeof startIdentity,'string');assert.match(startIdentity,/^[A-Za-z]{3} [A-Za-z]{3}\s+\d{1,2} \d{2}:\d{2}:\d{2} \d{4}$/);assert.ok(command.startsWith(executable+' '));assert.ok(command.includes('--user-data-dir='+profile));
 const worker=rows.find(r=>r.pid===workerPid),browser=rows.find(r=>r.pid===browserPid);assert.ok(worker&&browser);assert.equal(worker.uid,uid);assert.equal(browser.uid,uid);assert.equal(browser.pgid,browser.pid,'Puppeteer must lead its exact owned browser group');assert.notEqual(browser.pgid,worker.pgid,'Never own the worker group as a browser group');
 return Object.freeze({version:1,pid:browserPid,pgid:browser.pgid,uid,workerPid,qualificationPgid:worker.pgid,profile,executable,startIdentity,command,detached:true});
}
function captureManagedIdentity({child,profile,root,executable}){return validateManagedIdentity({rows:parseProcessRows(execFileSync('/bin/ps',['-o','pid=,pgid=,uid=','-p',[process.pid,child.pid].join(',')],{encoding:'utf8',timeout:2000,maxBuffer:65536})),browserPid:child.pid,workerPid:process.pid,uid:process.getuid(),profile,root,executable,args:child.spawnargs,startIdentity:execFileSync('/bin/ps',['-p',String(child.pid),'-o','lstart='],{encoding:'utf8',timeout:2000}).trim(),command:execFileSync('/bin/ps',['-p',String(child.pid),'-o','command='],{encoding:'utf8',timeout:2000,maxBuffer:65536}).trim()});}
function groupMembers(identity){const text=execFileSync('/bin/ps',['-axo','pid=,pgid=,uid='],{encoding:'utf8',timeout:2000,maxBuffer:1048576});const members=text.trim().split(/\n/).map(row=>row.trim().split(/\s+/).map(Number)).filter(row=>row[1]===identity.pgid);assert.ok(members.every(row=>row.length===3&&row[2]===identity.uid));return members;}
async function assertGroupDrained(identity){const deadline=Date.now()+3000;while(groupMembers(identity).length&&Date.now()<deadline)await new Promise(r=>setTimeout(r,50));assert.equal(groupMembers(identity).length,0,'Exact detached browser group must be absent');}
module.exports={validateManagedIdentity,captureManagedIdentity,assertGroupDrained};
